// FILE PATH: components/team/tabs/CMSTab.tsx
'use client';

import React, { useState } from 'react';
import {
  StudioCMSConfig, PortfolioShowcaseItem, RBACPermissions,
  STORAGE_KEYS, setStore,
} from '@/lib/store';
import {
  Plus, X, ExternalLink, Globe, BookOpen, Settings, Pencil, Save, Trash2,
} from 'lucide-react';

interface CMSTabProps {
  perms: RBACPermissions;
  cms: StudioCMSConfig;
  onCMSChange: (cms: StudioCMSConfig) => void;
}

export default function CMSTab({ perms, cms, onCMSChange }: CMSTabProps) {
  const [activeSection, setActiveSection] = useState<'PORTFOLIO' | 'ABOUT' | 'BOOKING'>('PORTFOLIO');
  const [editingPortfolioId, setEditingPortfolioId] = useState<string | null>(null);
  const [editingAbout, setEditingAbout] = useState(false);

  // Portfolio form
  const [portForm, setPortForm] = useState<Partial<PortfolioShowcaseItem>>({});
  const [showAddPort, setShowAddPort] = useState(false);

  // About form
  const [aboutForm, setAboutForm] = useState(cms.aboutUs);
  const [statsInput, setStatsInput] = useState(cms.aboutUs.stats.map((s) => `${s.label}:${s.value}`).join('\n'));

  // Booking form
  const [bookingForm, setBookingForm] = useState(cms.bookingSettings);
  const [scopesInput, setScopesInput] = useState(cms.bookingSettings.availableScopes.join('\n'));
  const [editingBooking, setEditingBooking] = useState(false);

  function saveCMS(updated: StudioCMSConfig) {
    setStore(STORAGE_KEYS.CMS, updated);
    onCMSChange(updated);
  }

  // Portfolio CRUD
  function addPortfolioItem() {
    if (!portForm.title || !portForm.liveUrl) return;
    const newItem: PortfolioShowcaseItem = {
      id: `port-${Date.now()}`,
      code: portForm.code || `PRJ // ${portForm.title?.slice(0, 8).toUpperCase()}`,
      title: portForm.title || '',
      category: portForm.category || 'WEB DEVELOPMENT',
      metrics: portForm.metrics || '60 FPS // PRODUCTION',
      description: portForm.description || '',
      liveUrl: portForm.liveUrl || '',
      repoUrl: portForm.repoUrl,
      featured: portForm.featured ?? false,
      tags: (portForm as Record<string, string | boolean>)['tagsRaw']
        ? String((portForm as Record<string, string | boolean>)['tagsRaw']).split(',').map((t: string) => t.trim())
        : [],
      thumbnailColor: portForm.thumbnailColor || '#dc2626',
    };
    const updated = { ...cms, portfolioShowcase: [...cms.portfolioShowcase, newItem] };
    saveCMS(updated);
    setPortForm({});
    setShowAddPort(false);
  }

  function updatePortfolioItem(id: string, changes: Partial<PortfolioShowcaseItem>) {
    const updated = {
      ...cms,
      portfolioShowcase: cms.portfolioShowcase.map((p) => p.id === id ? { ...p, ...changes } : p),
    };
    saveCMS(updated);
  }

  function deletePortfolioItem(id: string) {
    if (!confirm('Remove this portfolio item?')) return;
    const updated = { ...cms, portfolioShowcase: cms.portfolioShowcase.filter((p) => p.id !== id) };
    saveCMS(updated);
  }

  function saveAboutUs() {
    const stats = statsInput.split('\n').map((line) => {
      const [label, value] = line.split(':');
      return { label: (label || '').trim(), value: (value || '').trim() };
    }).filter((s) => s.label && s.value);
    const updated = { ...cms, aboutUs: { ...aboutForm, stats } };
    saveCMS(updated);
    setEditingAbout(false);
  }

  function saveBooking() {
    const scopes = scopesInput.split('\n').map((s) => s.trim()).filter(Boolean);
    const updated = { ...cms, bookingSettings: { ...bookingForm, availableScopes: scopes } };
    saveCMS(updated);
    setEditingBooking(false);
  }

  const sectionTabs = [
    { id: 'PORTFOLIO' as const, label: 'PORTFOLIO', icon: Globe, requirePerm: perms.canManagePortfolioCMS },
    { id: 'ABOUT' as const, label: 'ABOUT US', icon: BookOpen, requirePerm: perms.canManageAboutUs },
    { id: 'BOOKING' as const, label: 'BOOKING SETTINGS', icon: Settings, requirePerm: perms.canManageBookingSettings },
  ].filter((s) => s.requirePerm);

  return (
    <div className="p-6 sm:p-8">
      {/* Header */}
      <div className="mb-6">
        <p className="font-mono text-[10px] tracking-[0.3em] text-red-500 uppercase">WEBSITE MATRIX</p>
        <h2 className="text-2xl font-extrabold tracking-tight uppercase">PUBLIC CMS</h2>
        <p className="mt-1 text-sm text-zinc-400 font-mono">Manage what the world sees on the public studio website.</p>
      </div>

      {/* Section Tabs */}
      <div className="flex flex-wrap gap-2 mb-6 border-b border-white/8 pb-4">
        {sectionTabs.map(({ id, label, icon: Icon }) => (
          <button
            key={id}
            onClick={() => setActiveSection(id)}
            className={`flex items-center space-x-2 px-4 py-2.5 font-mono text-xs tracking-widest border uppercase transition-colors ${
              activeSection === id ? 'border-red-500 bg-red-600/20 text-white' : 'border-white/10 text-zinc-400 hover:text-white'
            }`}
          >
            <Icon className="w-3.5 h-3.5" />
            <span>{label}</span>
          </button>
        ))}
      </div>

      {/* ── PORTFOLIO SHOWCASE ────────────────────────────────── */}
      {activeSection === 'PORTFOLIO' && perms.canManagePortfolioCMS && (
        <div className="space-y-5">
          <div className="flex items-center justify-between">
            <p className="font-mono text-xs text-zinc-400">
              {cms.portfolioShowcase.length} projects · {cms.portfolioShowcase.filter((p) => p.featured).length} featured on homepage
            </p>
            <button
              onClick={() => setShowAddPort(!showAddPort)}
              className="flex items-center space-x-2 border border-red-500/50 bg-red-950/20 px-4 py-2 font-mono text-[10px] text-red-400 uppercase hover:bg-red-600/20 transition-colors"
            >
              <Plus className="w-3 h-3" />
              <span>ADD PROJECT</span>
            </button>
          </div>

          {/* Add Form */}
          {showAddPort && (
            <div className="border border-red-500/40 bg-[#080808] p-5 hud-clip space-y-3">
              <div className="flex items-center justify-between">
                <p className="font-mono text-xs text-red-400 uppercase font-bold">ADD PORTFOLIO ITEM</p>
                <button onClick={() => setShowAddPort(false)}><X className="w-4 h-4 text-zinc-500" /></button>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {[
                  { label: 'Title *', key: 'title', ph: 'AETHERIUS QUANTUM TELEMETRY' },
                  { label: 'Code', key: 'code', ph: 'PRJ // HYPERION-GL' },
                  { label: 'Category', key: 'category', ph: 'CUSTOM GLSL / NEXT.JS' },
                  { label: 'Metrics', key: 'metrics', ph: '120 FPS LOCKED' },
                  { label: 'Live URL *', key: 'liveUrl', ph: 'https://...' },
                  { label: 'Repo URL', key: 'repoUrl', ph: 'https://github.com/...' },
                  { label: 'Tags (comma)', key: 'tagsRaw', ph: 'WebGL, GLSL, Real-Time' },
                  { label: 'Accent Color', key: 'thumbnailColor', ph: '#dc2626' },
                ].map(({ label, key, ph }) => (
                  <div key={key}>
                    <label className="block font-mono text-[9px] text-zinc-400 mb-1 uppercase tracking-widest">{label}</label>
                    <input
                      value={String((portForm as Record<string, unknown>)[key] || '')}
                      onChange={(e) => setPortForm((p) => ({ ...p, [key]: e.target.value }))}
                      placeholder={ph}
                      className="w-full border border-white/15 bg-black px-3 py-2 text-sm text-white focus:border-red-500 focus:outline-none"
                    />
                  </div>
                ))}
                <div className="sm:col-span-2">
                  <label className="block font-mono text-[9px] text-zinc-400 mb-1 uppercase tracking-widest">Description</label>
                  <textarea
                    value={portForm.description || ''}
                    onChange={(e) => setPortForm((p) => ({ ...p, description: e.target.value }))}
                    rows={2}
                    placeholder="Project description for the portfolio card..."
                    className="w-full border border-white/15 bg-black px-3 py-2 text-sm text-white focus:border-red-500 focus:outline-none resize-none"
                  />
                </div>
              </div>
              <div className="flex items-center space-x-3">
                <button
                  type="button"
                  onClick={() => setPortForm((p) => ({ ...p, featured: !p.featured }))}
                  className={`px-4 py-2 border font-mono text-[9px] uppercase transition-colors ${portForm.featured ? 'border-amber-500 bg-amber-950/30 text-amber-400' : 'border-white/15 text-zinc-400'}`}
                >
                  {portForm.featured ? '★ FEATURED' : '☆ FEATURED'}
                </button>
                <button onClick={addPortfolioItem} className="border border-emerald-500/50 bg-emerald-950/20 px-5 py-2 font-mono text-[9px] text-emerald-400 uppercase hover:bg-emerald-600/20 transition-colors">
                  + ADD TO SHOWCASE
                </button>
              </div>
            </div>
          )}

          {/* Portfolio Items */}
          <div className="space-y-3">
            {cms.portfolioShowcase.map((item) => (
              <div key={item.id} className="border border-white/10 bg-[#060606] p-5 hud-clip">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-center space-x-3 flex-1 min-w-0">
                    <div className="w-10 h-10 shrink-0" style={{ background: item.thumbnailColor }}>
                      <div className="w-full h-full hud-clip" style={{ background: item.thumbnailColor }} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <p className="font-mono text-[9px] text-zinc-500">{item.code}</p>
                        {item.featured && <span className="font-mono text-[8px] border border-amber-500/50 bg-amber-950/30 text-amber-400 px-1.5 py-0.5">FEATURED</span>}
                      </div>
                      <p className="font-semibold text-white text-sm">{item.title}</p>
                      <p className="font-mono text-[9px] text-zinc-400">{item.category} // {item.metrics}</p>
                      <p className="text-xs text-zinc-400 mt-1 line-clamp-2">{item.description}</p>
                    </div>
                  </div>
                  <div className="flex items-center space-x-2 shrink-0">
                    {item.liveUrl && (
                      <a href={item.liveUrl} target="_blank" rel="noopener noreferrer" className="text-zinc-500 hover:text-cyan-400">
                        <ExternalLink className="w-4 h-4" />
                      </a>
                    )}
                    <button
                      onClick={() => updatePortfolioItem(item.id, { featured: !item.featured })}
                      className={`font-mono text-[9px] border px-2.5 py-1.5 transition-colors ${item.featured ? 'border-amber-500/50 text-amber-400' : 'border-white/15 text-zinc-500 hover:text-white'}`}
                    >
                      {item.featured ? 'UNFEATURE' : 'FEATURE'}
                    </button>
                    <button
                      onClick={() => deletePortfolioItem(item.id)}
                      className="text-zinc-600 hover:text-red-500 transition-colors"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── ABOUT US ─────────────────────────────────────────── */}
      {activeSection === 'ABOUT' && perms.canManageAboutUs && (
        <div className="space-y-5">
          <div className="flex items-center justify-between">
            <p className="font-mono text-xs text-zinc-400">Studio identity, manifesto, and key stats shown on public website.</p>
            <button
              onClick={() => setEditingAbout(!editingAbout)}
              className="flex items-center space-x-2 border border-white/15 px-4 py-2 font-mono text-[10px] text-zinc-300 hover:border-red-500 uppercase transition-colors"
            >
              <Pencil className="w-3.5 h-3.5" />
              <span>{editingAbout ? 'CANCEL' : 'EDIT'}</span>
            </button>
          </div>

          {editingAbout ? (
            <div className="border border-white/10 bg-[#060606] p-5 space-y-4 hud-clip">
              {[
                { label: 'Hero Tagline', key: 'heroTagline' },
                { label: 'Sub Tagline', key: 'subTagline' },
                { label: 'Founded Year', key: 'foundedYear' },
                { label: 'Location', key: 'location' },
                { label: 'Contact Email', key: 'contactEmail' },
                { label: 'Team Highlight Text', key: 'teamHighlight' },
              ].map(({ label, key }) => (
                <div key={key}>
                  <label className="block font-mono text-[9px] text-zinc-400 mb-1 uppercase tracking-widest">{label}</label>
                  <input
                    value={(aboutForm as unknown as Record<string, string>)[key] || ''}
                    onChange={(e) => setAboutForm((p) => ({ ...p, [key]: e.target.value }))}
                    className="w-full border border-white/15 bg-black px-3 py-2.5 text-sm text-white focus:border-red-500 focus:outline-none"
                  />
                </div>
              ))}
              <div>
                <label className="block font-mono text-[9px] text-zinc-400 mb-1 uppercase tracking-widest">Manifesto</label>
                <textarea
                  value={aboutForm.manifesto}
                  onChange={(e) => setAboutForm((p) => ({ ...p, manifesto: e.target.value }))}
                  rows={4}
                  className="w-full border border-white/15 bg-black px-3 py-2.5 text-sm text-white focus:border-red-500 focus:outline-none resize-none"
                />
              </div>
              <div>
                <label className="block font-mono text-[9px] text-zinc-400 mb-1 uppercase tracking-widest">Stats (one per line: Label:Value)</label>
                <textarea
                  value={statsInput}
                  onChange={(e) => setStatsInput(e.target.value)}
                  rows={4}
                  placeholder="FPS Locked:120&#10;Projects Shipped:12+&#10;Uptime:99.99%"
                  className="w-full border border-white/15 bg-black px-3 py-2.5 font-mono text-sm text-white focus:border-red-500 focus:outline-none resize-none"
                />
              </div>
              <button onClick={saveAboutUs} className="flex items-center space-x-2 border border-emerald-500/50 bg-emerald-950/20 px-5 py-2.5 font-mono text-xs text-emerald-400 uppercase hover:bg-emerald-600/20 transition-colors">
                <Save className="w-3.5 h-3.5" />
                <span>SAVE CHANGES</span>
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
              <div className="border border-white/10 bg-[#060606] p-5 hud-clip space-y-3">
                {[
                  { label: 'Hero Tagline', value: cms.aboutUs.heroTagline },
                  { label: 'Sub Tagline', value: cms.aboutUs.subTagline },
                  { label: 'Founded', value: cms.aboutUs.foundedYear },
                  { label: 'Location', value: cms.aboutUs.location },
                  { label: 'Contact', value: cms.aboutUs.contactEmail },
                ].map(({ label, value }) => (
                  <div key={label} className="flex justify-between items-start gap-3">
                    <span className="font-mono text-[9px] text-zinc-500 shrink-0">{label}</span>
                    <span className="font-mono text-[10px] text-white text-right">{value}</span>
                  </div>
                ))}
              </div>
              <div className="border border-white/10 bg-[#060606] p-5 hud-clip">
                <p className="font-mono text-[9px] text-zinc-500 mb-2 uppercase tracking-widest">KEY STATS</p>
                <div className="grid grid-cols-2 gap-3">
                  {cms.aboutUs.stats.map((s) => (
                    <div key={s.label} className="text-center border border-white/8 p-3">
                      <p className="text-xl font-extrabold text-red-400">{s.value}</p>
                      <p className="font-mono text-[8px] text-zinc-500 tracking-widest mt-0.5">{s.label}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ── BOOKING SETTINGS ─────────────────────────────────── */}
      {activeSection === 'BOOKING' && perms.canManageBookingSettings && (
        <div className="space-y-5">
          <div className="flex items-center justify-between">
            <p className="font-mono text-xs text-zinc-400">Control what clients see and can book from the public inquiry form.</p>
            <button
              onClick={() => setEditingBooking(!editingBooking)}
              className="flex items-center space-x-2 border border-white/15 px-4 py-2 font-mono text-[10px] text-zinc-300 hover:border-red-500 uppercase transition-colors"
            >
              <Pencil className="w-3.5 h-3.5" />
              <span>{editingBooking ? 'CANCEL' : 'EDIT'}</span>
            </button>
          </div>

          <div className="border border-white/10 bg-[#060606] p-5 hud-clip space-y-4">
            {editingBooking ? (
              <>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {[
                    { label: 'Response Time', key: 'responseTime' },
                    { label: 'Minimum Budget', key: 'minimumBudget' },
                    { label: 'Calendar Link', key: 'calendarLink' },
                  ].map(({ label, key }) => (
                    <div key={key}>
                      <label className="block font-mono text-[9px] text-zinc-400 mb-1 uppercase tracking-widest">{label}</label>
                      <input
                        value={(bookingForm as unknown as Record<string, string | boolean>)[key] as string || ''}
                        onChange={(e) => setBookingForm((p) => ({ ...p, [key]: e.target.value }))}
                        className="w-full border border-white/15 bg-black px-3 py-2.5 text-sm text-white focus:border-red-500 focus:outline-none"
                      />
                    </div>
                  ))}
                  <div className="flex items-center space-x-3 pt-5">
                    <button
                      onClick={() => setBookingForm((p) => ({ ...p, enabled: !p.enabled }))}
                      className={`px-4 py-2.5 border font-mono text-[9px] uppercase transition-colors ${bookingForm.enabled ? 'border-emerald-500 bg-emerald-950/30 text-emerald-400' : 'border-red-500 bg-red-950/30 text-red-400'}`}
                    >
                      BOOKING: {bookingForm.enabled ? 'ENABLED' : 'DISABLED'}
                    </button>
                  </div>
                </div>
                <div>
                  <label className="block font-mono text-[9px] text-zinc-400 mb-1 uppercase tracking-widest">Available Scopes (one per line)</label>
                  <textarea
                    value={scopesInput}
                    onChange={(e) => setScopesInput(e.target.value)}
                    rows={5}
                    className="w-full border border-white/15 bg-black px-3 py-2.5 font-mono text-sm text-white focus:border-red-500 focus:outline-none resize-none"
                  />
                </div>
                <button onClick={saveBooking} className="flex items-center space-x-2 border border-emerald-500/50 bg-emerald-950/20 px-5 py-2.5 font-mono text-xs text-emerald-400 uppercase hover:bg-emerald-600/20 transition-colors">
                  <Save className="w-3.5 h-3.5" />
                  <span>SAVE SETTINGS</span>
                </button>
              </>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div className="space-y-3">
                  {[
                    { label: 'STATUS', value: cms.bookingSettings.enabled ? 'ENABLED' : 'DISABLED', valueColor: cms.bookingSettings.enabled ? 'text-emerald-400' : 'text-red-400' },
                    { label: 'RESPONSE TIME', value: cms.bookingSettings.responseTime, valueColor: 'text-white' },
                    { label: 'MIN. BUDGET', value: cms.bookingSettings.minimumBudget, valueColor: 'text-emerald-400' },
                    { label: 'CALENDAR LINK', value: cms.bookingSettings.calendarLink || 'Not set', valueColor: 'text-zinc-400' },
                  ].map(({ label, value, valueColor }) => (
                    <div key={label} className="flex justify-between items-center">
                      <span className="font-mono text-[9px] text-zinc-500">{label}</span>
                      <span className={`font-mono text-[10px] ${valueColor}`}>{value}</span>
                    </div>
                  ))}
                </div>
                <div>
                  <p className="font-mono text-[9px] text-zinc-500 mb-2 uppercase tracking-widest">AVAILABLE SCOPES</p>
                  <div className="space-y-1.5">
                    {cms.bookingSettings.availableScopes.map((scope) => (
                      <p key={scope} className="font-mono text-[9px] text-zinc-300 border border-white/8 px-3 py-1.5">{scope}</p>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
